put('assets/base.css','''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;font-family:Arial,Helvetica,sans-serif;line-height:1.6;color:var(--ink,#202a23);background:var(--paper,#f7f6f0)}h1,h2,h3,p{margin:0}h1,h2,h3{line-height:1.08;font-weight:500}h1{font-size:clamp(3rem,6.8vw,6.8rem);letter-spacing:-.055em}h2{font-size:clamp(2.2rem,4.3vw,4.6rem);letter-spacing:-.045em}h3{font-size:1.6rem;letter-spacing:-.025em}p{max-width:65ch}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}button{cursor:pointer}button:disabled{cursor:default;opacity:.55}img{display:block;width:100%;height:100%;object-fit:cover}svg{max-width:100%}:focus-visible{outline:3px solid var(--accent,#426f49);outline-offset:5px}.skip{position:fixed;top:-100px;left:20px;background:white;color:#111;padding:12px;z-index:100}.skip:focus{top:8px}.demo-bar{background:var(--ink,#202a23);color:var(--paper,#f7f6f0);font-size:11px;letter-spacing:.05em;text-align:center;padding:8px 16px}.demo-bar a{white-space:nowrap;text-decoration:underline;text-underline-offset:3px}.shell{width:min(1280px,calc(100% - 96px));margin:auto}.nav{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:92px;border-bottom:1px solid var(--line,#d9ddd2)}.brand{font-size:27px;font-weight:700;letter-spacing:-1.3px;display:flex;align-items:center;gap:10px}.brand small{font:10px Arial;letter-spacing:2px;margin-left:6px}.links{display:flex;align-items:center;gap:28px;font-size:13px}.links a:hover{opacity:.65}.menu-toggle{display:none;background:none;border:1px solid var(--line);padding:8px 13px;color:inherit}.btn{display:inline-flex;justify-content:center;align-items:center;gap:24px;padding:16px 25px;border:1px solid transparent;background:var(--accent,#253f2c);color:var(--button-ink,#fff);font-size:13px;font-weight:600;line-height:1.4;transition:transform .2s,background .2s}.btn:hover{transform:translateY(-2px)}.btn.light{background:transparent;color:inherit;border-color:var(--line,#ccc)}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:.19em;font-weight:600;display:block;margin-bottom:24px}.muted{color:var(--muted,#667063)}.lead{font-size:18px;line-height:1.7}.serif{font-family:Georgia,'Times New Roman',serif;font-weight:400}.italic{font-style:italic}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:32px}.section{padding:104px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:40px;margin-bottom:48px}.section-head p{max-width:36ch}.grid{display:grid;gap:24px}.g2{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:repeat(3,minmax(0,1fr))}.g4{grid-template-columns:repeat(4,minmax(0,1fr))}.label{font-size:11px;letter-spacing:.13em;text-transform:uppercase}.rule{border-top:1px solid var(--line,#d9ddd2)}.pill{display:inline-flex;padding:6px 12px;border:1px solid var(--line);border-radius:100px;font-size:11px}.chips{display:flex;gap:8px;flex-wrap:wrap}.chip{border:1px solid var(--line);background:transparent;color:inherit;padding:10px 18px;border-radius:40px;font-size:12px}.chip[aria-pressed=true]{background:var(--ink);border-color:var(--ink);color:var(--paper)}.faq{border-top:1px solid var(--line)}details{border-bottom:1px solid var(--line);padding:23px 0}summary{cursor:pointer;font-size:17px;list-style:none;display:flex;justify-content:space-between;gap:24px}summary::-webkit-details-marker{display:none}summary:after{content:'+';font-size:22px}details[open] summary:after{content:'−'}details p{padding-top:18px;color:var(--muted);font-size:14px}.footer{padding:40px 0;border-top:1px solid var(--line)}.footer-row{display:flex;justify-content:space-between;gap:24px;align-items:center}.footer p{font-size:12px}.footer a{text-decoration:underline;text-underline-offset:4px}.fine{font-size:11px;color:var(--muted)}.field{display:flex;flex-direction:column;gap:7px;font-size:12px}.field input,.field select,.field textarea{width:100%;min-height:48px;padding:12px;border:1px solid var(--line,#ccc);background:var(--paper,#fff);color:var(--ink);border-radius:3px}.field textarea{min-height:110px;resize:vertical}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.span2{grid-column:1/-1}.dialog{width:min(570px,calc(100% - 32px));max-height:90dvh;padding:36px;border:0;background:var(--paper);color:var(--ink);box-shadow:0 20px 100px #0005}.dialog::backdrop{background:#102018b0;backdrop-filter:blur(6px)}.dialog h2{font-size:2.2rem;margin:16px 0}.dialog p{font-size:14px;margin:12px 0 22px}.dialog-close{float:right;background:transparent;border:1px solid var(--line);color:inherit;padding:5px 12px}.status{font-size:14px;padding:14px;margin-top:20px;background:var(--soft,#e7eddc);border-left:3px solid var(--accent)}.status:empty{display:none}[hidden]{display:none!important}.number{font:12px monospace;color:var(--muted)}.reveal{animation:appear .7s both}@keyframes appear{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:none}}@media(max-width:900px){.shell{width:calc(100% - 48px)}.links{gap:16px}.g4{grid-template-columns:repeat(2,1fr)}.section{padding:75px 0}.section-head{align-items:start}}@media(max-width:650px){.demo-bar{font-size:9px}.shell{width:calc(100% - 36px)}h1{font-size:3.5rem}h2{font-size:2.65rem}.nav{min-height:78px;position:relative;flex-wrap:wrap}.brand{font-size:23px}.brand small{font-size:8px}.menu-toggle{display:block}.links{display:none;width:100%;padding:8px 0 24px;flex-direction:column;align-items:stretch;gap:20px}.links.open{display:flex}.g2,.g3,.g4{grid-template-columns:1fr}.section{padding:58px 0}.section-head{flex-direction:column;gap:24px;margin-bottom:32px}.lead{font-size:16px}.footer-row{flex-direction:column;align-items:start}.form-grid{grid-template-columns:1fr}.span2{grid-column:auto}.dialog{padding:24px}.btn{padding:14px 20px}.eyebrow{margin-bottom:18px}.actions{margin-top:25px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}}''')
put('assets/base.js','''document.querySelectorAll('.menu-toggle').forEach(b=>{b.addEventListener('click',()=>{const n=document.getElementById(b.getAttribute('aria-controls'));const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));n.classList.toggle('open',open)});});document.querySelectorAll('.links a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.links').forEach(n=>n.classList.remove('open'));document.querySelectorAll('.menu-toggle').forEach(b=>b.setAttribute('aria-expanded','false'))}));document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.dialog).showModal()));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));document.querySelectorAll('[data-demo-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();f.querySelector('[role="status"]').textContent='Demonstração concluída. Nenhum dado foi enviado ou armazenado.'}));''')
def head(title,desc,slug,css=''):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#253f2c"><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><title>{title}</title><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../assets/base.css"><link rel="stylesheet" href="style.css"><script src="../assets/base.js" defer></script><script src="app.js" defer></script></head><body class="{slug}"><a class="skip" href="#main">Pular para o conteúdo</a><div class="demo-bar">PROJETO CONCEITUAL · Marca fictícia · <a href="../">Ver todas as demos ↗</a></div>'''
def nav(brand,links,cta,target):
 return f'''<header class="shell"><nav class="nav" aria-label="Navegação principal"><a class="brand" href="#">{brand}</a><button class="menu-toggle" aria-expanded="false" aria-controls="nav-links">Menu</button><div class="links" id="nav-links">{''.join(f'<a href="#{i}">{t}</a>' for i,t in links)}<a class="btn" href="#{target}">{cta} ↗</a></div></nav></header>'''
def footer(brand):
 return f'''<footer class="footer shell"><div class="footer-row"><a class="brand" href="#">{brand}</a><p>Design e desenvolvimento · Gabriel Saturnino<br><span class="muted">Projeto demonstrativo. Marca, ofertas e valores fictícios.</span></p><a class="label" href="../">Explorar outros projetos ↗</a></div></footer></body></html>'''
def faq(items):
 return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
# FORMA
put('forma/index.html',head('Forma — Arquitetura para viver','Estúdio conceitual de arquitetura. Projetos residenciais, interiores e espaços comerciais.','forma')+nav('forma<span class="brand-dot">®</span>',[('projetos','Projetos'),('estudio','O estúdio'),('processo','Processo')],'Vamos conversar','contato')+'''<main id="main"><section class="shell hero"><div class="hero-top"><span class="eyebrow">Arquitetura · Interiores · Essência</span><span class="label muted">Belo Horizonte, MG<br>Perspectiva brasileira</span></div><h1>Espaços que fazem<br>sentido. <span class="serif italic">Para você.</span></h1><div class="hero-bottom"><p>Entre a luz, a matéria e a sua história,<br>encontramos um jeito único de habitar.</p><a class="circle-link" href="#projetos" aria-label="Conhecer projetos">↙</a></div><figure class="hero-image"><img src="../assets/architecture.svg" alt="Ilustração autoral de casa contemporânea com concreto, madeira e jardim" fetchpriority="high"><figcaption><span>01 / Casa Horizonte</span><span>Estudo conceitual · Residencial</span></figcaption></figure></section><section class="shell section" id="projetos"><div class="section-head"><div><span class="eyebrow">Portfólio selecionado</span><h2>Um olhar.<br><span class="serif italic">Muitas possibilidades.</span></h2></div><div class="chips" role="group" aria-label="Filtrar projetos"><button class="chip" data-filter="all" aria-pressed="true">Todos</button><button class="chip" data-filter="residencial" aria-pressed="false">Residencial</button><button class="chip" data-filter="interiores" aria-pressed="false">Interiores</button><button class="chip" data-filter="comercial" aria-pressed="false">Comercial</button></div></div><div class="grid g2 projects"><button class="project" data-category="residencial" data-project="horizonte"><div class="project-img"><img src="../assets/architecture.svg" loading="lazy" alt="Casa Horizonte, estudo arquitetônico"></div><div class="project-meta"><h3>Casa Horizonte</h3><span>Residencial · 240 m² ↗</span></div></button><button class="project" data-category="interiores" data-project="refugio"><div class="project-img"><img src="../assets/interior.svg" loading="lazy" alt="Interior com sofá terracota e janela ampla"></div><div class="project-meta"><h3>Refúgio urbano</h3><span>Interiores · 86 m² ↗</span></div></button><button class="project" data-category="comercial" data-project="atelie"><div class="project-img commercial"><img src="../assets/interior.svg" loading="lazy" alt="Estudo de interior acolhedor para ateliê"></div><div class="project-meta"><h3>Ateliê de encontros</h3><span>Comercial · 120 m² ↗</span></div></button></div><p class="fine" style="margin-top:20px">Projetos e metragens ilustrativos. Explore os estudos clicando nas imagens.</p></section><section class="studio" id="estudio"><div class="shell section grid g2"><div><span class="eyebrow">Menos excessos. Mais significado.</span><h2>A boa arquitetura<br><span class="serif italic">começa na escuta.</span></h2></div><div class="studio-copy"><p class="lead">A Forma é um estúdio imaginado para aproximar arquitetura e vida cotidiana. Um lugar onde o seu jeito de viver orienta cada escolha.</p><p>Materiais honestos, luz natural e ambientes que respiram. Nossa proposta é explorar o essencial, respeitando o contexto, a rotina e o orçamento de cada projeto.</p><div class="grid g2 values"><div><span class="number">01</span><h3>Luz como matéria</h3><p>Ambientes pensados a partir da orientação e do conforto.</p></div><div><span class="number">02</span><h3>Beleza com função</h3><p>Escolhas que conectam estética e uso real.</p></div></div></div></div></section><section class="shell section" id="processo"><div class="section-head"><div><span class="eyebrow">Do primeiro traço à entrega</span><h2>Clareza em<br><span class="serif italic">cada etapa.</span></h2></div><p class="muted">Um processo próximo e transparente para transformar ideias em espaços possíveis.</p></div><div class="grid g4 steps"><article><span class="number">01 / DESCOBRIR</span><h3>Seu jeito de viver</h3><p>Conversamos sobre desejos, rotina, referências e limites.</p></article><article><span class="number">02 / CONCEBER</span><h3>Dar forma à ideia</h3><p>Estudamos layout, volumes, materiais e iluminação.</p></article><article><span class="number">03 / DETALHAR</span><h3>Planejar o possível</h3><p>Organizamos desenhos e especificações para execução.</p></article><article><span class="number">04 / ACOMPANHAR</span><h3>Cuidar do resultado</h3><p>Alinhamos decisões e esclarecemos dúvidas ao longo do caminho.</p></article></div></section><section class="shell section rule"><div class="grid g2"><h2>Antes de<br><span class="serif italic">começar.</span></h2>'''+faq([('Que tipos de projeto estão representados?','Residências, interiores e espaços comerciais. Todos os estudos desta página são conceituais e não representam obras executadas.'),('Como funciona o orçamento?','Em um serviço real, escopo, área, complexidade e acompanhamento orientariam uma proposta individual. Esta demo não comercializa serviços de arquitetura.'),('Posso reformar apenas um ambiente?','A interface foi pensada para permitir o contato tanto para ambientes pontuais quanto para projetos completos.')])+'''</div></section><section class="contact section" id="contato"><div class="shell grid g2"><div><span class="eyebrow">Seu próximo espaço começa aqui</span><h2>Vamos dar forma<br><span class="serif italic">à sua ideia?</span></h2><p class="lead">Conte um pouco do que você imagina.</p><span class="fine">Formulário demonstrativo · sem envio de dados</span></div><form data-demo-form class="form-grid"><label class="field">Nome<input name="nome" required autocomplete="name" placeholder="Como podemos te chamar?"></label><label class="field">E-mail<input type="email" name="email" required autocomplete="email" placeholder="voce@exemplo.com"></label><label class="field span2">Tipo de projeto<select name="tipo"><option>Residencial</option><option>Interiores</option><option>Comercial</option></select></label><label class="field span2">Sua ideia<textarea name="ideia" required placeholder="Conte sobre seu espaço e o que deseja transformar"></textarea></label><button class="btn span2" type="submit">Simular envio do projeto ↗</button><p role="status" class="status span2" aria-live="polite"></p></form></div></section></main><dialog class="dialog" id="project-dialog"><button class="dialog-close" data-close aria-label="Fechar projeto">×</button><span class="eyebrow">Estudo conceitual</span><h2 id="project-title"></h2><p id="project-copy"></p><div class="project-facts" id="project-facts"></div><p class="fine">Ilustração autoral. Não representa uma obra real.</p></dialog>'''+footer('forma®'))
put('forma/style.css',''':root{--paper:#f2f0e9;--ink:#333b31;--accent:#3e4b38;--muted:#73786b;--line:#d4d6ca;--soft:#e5e8dc}.brand-dot{font-size:14px;align-self:start}.hero{padding-top:52px}.hero-top,.hero-bottom{display:flex;justify-content:space-between;align-items:start;gap:20px}.hero-top{margin-bottom:30px}.hero-top>.label{text-align:right;font-size:9px}.hero h1{font-size:clamp(3.2rem,6.7vw,6.7rem)}.hero-bottom{margin:30px 0 42px;align-items:center}.hero-bottom p{font-size:15px}.circle-link{border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;width:64px;height:64px;font-size:27px}.hero-image{margin:0;height:570px;position:relative;overflow:hidden}.hero-image img{object-position:center 60%}.hero-image figcaption{position:absolute;bottom:20px;left:25px;right:25px;color:white;display:flex;justify-content:space-between;font-size:11px;text-shadow:0 1px 10px #000}.project{border:0;text-align:left;padding:0;background:transparent;color:inherit}.project-img{height:350px;overflow:hidden}.project-img img{transition:transform .5s}.project:hover img{transform:scale(1.03)}.project-meta{padding:20px 0;display:flex;justify-content:space-between;align-items:center;gap:14px}.project-meta h3{font-size:23px}.project-meta span{font-size:11px;color:var(--muted)}.projects .project:last-child{grid-column:1/-1}.projects .project:last-child .project-img{height:350px}.commercial img{object-position:50% 55%;filter:hue-rotate(22deg) saturate(.65)}.studio{background:#e5e7dc}.studio-copy>p+p{margin-top:24px;font-size:14px;color:var(--muted)}.values{margin-top:42px}.values h3{font-size:20px;margin:12px 0}.values p,.steps p{font-size:13px;color:var(--muted)}.steps article{border-top:1px solid var(--line);padding-top:22px}.steps h3{font-size:23px;margin:28px 0 16px}.contact{background:#dce1d0}.contact h2{margin-bottom:30px}.contact .fine{display:block;margin-top:20px}.contact .grid{gap:80px}.project-facts{padding:20px;border:1px solid var(--line);font-size:13px}@media(max-width:650px){.hero{padding-top:30px}.hero-top>.label{display:none}.hero-image{height:350px}.project-img{height:280px}.project-meta{align-items:start;flex-direction:column;gap:8px}.projects .project:last-child{grid-column:auto}.projects .project:last-child .project-img{height:280px}.contact .grid{gap:36px}.hero-image figcaption span:last-child{display:none}}''')
put('forma/app.js','''const projects={horizonte:{title:'Casa Horizonte',copy:'Uma casa organizada em torno da paisagem. O estudo explora aberturas amplas, circulação fluida e materiais naturais para aproximar interior e exterior.',facts:'Residencial · Área ilustrativa: 240 m² · Madeira, concreto e vidro'},refugio:{title:'Refúgio urbano',copy:'Um apartamento que desacelera o ritmo da cidade. Tons terrosos, luz suave e mobiliário de linhas simples estruturam um ambiente acolhedor.',facts:'Interiores · Área ilustrativa: 86 m² · Paleta terracota e madeira'},atelie:{title:'Ateliê de encontros',copy:'Um espaço comercial pensado para receber. A proposta combina áreas de exposição, uma mesa de conversa e circulação acessível.',facts:'Comercial · Área ilustrativa: 120 m² · Layout flexível'}};document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-category]').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)}));document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const p=projects[b.dataset.project];document.getElementById('project-title').textContent=p.title;document.getElementById('project-copy').textContent=p.copy;document.getElementById('project-facts').textContent=p.facts;document.getElementById('project-dialog').showModal()}));''')
# AURORA
put('aurora/index.html',head('Aurora — O essencial para sua pele','Uma experiência conceitual de skincare com rotina simples e design natural.','aurora')+nav('aurora<span class="sun">✳</span>',[('colecao','A coleção'),('filosofia','Nossa essência'),('rotina','Sua rotina')],'Descobrir meu ritual','rotina')+'''<main id="main"><section class="hero"><div class="shell hero-layout"><div class="hero-copy"><span class="eyebrow">Um momento seu. Todos os dias.</span><h1>Menos passos.<br>Mais <span class="serif italic">cuidado.</span></h1><p class="lead">Uma pausa no excesso. Conheça uma coleção conceitual que transforma o cuidado diário em um ritual simples.</p><div class="actions"><a class="btn" href="#colecao">Explorar a coleção ↗</a><a class="text-link" href="#filosofia">Conheça a essência ↓</a></div><div class="hero-notes"><span>Fórmulas ilustrativas</span><span>Design consciente</span><span>Rotina essencial</span></div></div><div class="hero-art"><img src="../assets/cosmetics.svg" alt="Ilustração de frascos Aurora em tons de oliva e creme com folhas" fetchpriority="high"><div class="art-tag"><span class="serif">O cuidado começa<br>com uma pausa.</span><span>✳</span></div></div></div></section><div class="ticker" aria-label="Princípios da coleção"><span>O essencial, bem feito.</span><span>✳</span><span>Um ritual possível.</span><span>✳</span><span>Cuidado com intenção.</span></div><section class="shell section" id="colecao"><div class="section-head"><div><span class="eyebrow">Três gestos, um ritual</span><h2>Sua pele.<br><span class="serif italic">Seu tempo.</span></h2></div><p class="muted">Uma linha fictícia de produtos para demonstrar uma experiência de marca e descoberta. Valores apenas ilustrativos.</p></div><div class="grid g3 products"><article class="product"><div class="product-art clean"><span class="pill">01 · Limpar</span><div class="bottle"><span>aurora</span><small>ESSENCIAL<br>gel de limpeza</small><em>150 ml</em></div></div><div class="product-title"><h3>Começo leve</h3><span>R$ 59</span></div><p>Gel de limpeza · O primeiro gesto da rotina.</p><button class="product-link" data-product="limpar">Explorar produto ↗</button></article><article class="product"><div class="product-art serum"><span class="pill">02 · Cuidar</span><div class="dropper"><div></div><span>aurora</span><small>EQUILÍBRIO<br>sérum facial</small><em>30 ml</em></div></div><div class="product-title"><h3>Gota a gota</h3><span>R$ 89</span></div><p>Sérum facial · Uma textura para descobrir.</p><button class="product-link" data-product="cuidar">Explorar produto ↗</button></article><article class="product"><div class="product-art cream"><span class="pill">03 · Hidratar</span><div class="jar"><span>aurora</span><small>ABRAÇO<br>creme facial</small><em>50 g</em></div></div><div class="product-title"><h3>Toque de calma</h3><span>R$ 79</span></div><p>Creme facial · Finalize o seu momento.</p><button class="product-link" data-product="hidratar">Explorar produto ↗</button></article></div></section><section class="philosophy" id="filosofia"><div class="shell section grid g2"><div class="botanical"><span class="orb orb1"></span><span class="orb orb2"></span><span class="serif">O natural<br>é <i>sentir.</i></span><small>Estudo visual · Aurora</small></div><div class="philosophy-copy"><span class="eyebrow">A beleza de simplificar</span><h2>Um ritual que<br><span class="serif italic">cabe na vida.</span></h2><p class="lead">Nem toda rotina precisa de muitos passos. Nossa proposta de marca valoriza escolhas claras, texturas agradáveis e um momento de presença.</p><div class="principle"><span>01</span><div><h3>Clareza, sempre</h3><p>Informações fáceis de encontrar e de entender.</p></div></div><div class="principle"><span>02</span><div><h3>Sem promessas impossíveis</h3><p>Uma experiência de cuidado, sem alegações milagrosas.</p></div></div><div class="principle"><span>03</span><div><h3>Design que acolhe</h3><p>Do frasco à navegação, espaço para respirar.</p></div></div></div></div></section><section class="shell section" id="rotina"><div class="ritual"><div><span class="eyebrow">Encontre seu momento</span><h2>Qual ritual<br><span class="serif italic">combina com você?</span></h2><p>Escolha quando prefere desacelerar e explore uma sugestão de experiência.</p><p class="fine">Quiz de demonstração. Não é orientação dermatológica.</p></div><div class="quiz"><span class="label">Em qual momento você quer sua pausa?</span><div class="quiz-options" role="group" aria-label="Momento do ritual"><button data-ritual="manha" aria-pressed="true">☀ <span>Pela manhã</span></button><button data-ritual="noite" aria-pressed="false">☾ <span>À noite</span></button><button data-ritual="simples" aria-pressed="false">✳ <span>No meu tempo</span></button></div><div class="quiz-result" aria-live="polite"><span class="eyebrow" id="ritual-label">Para começar com leveza</span><h3 id="ritual-title">Seu começo de dia</h3><p id="ritual-copy">Uma limpeza gentil e um momento para hidratar. Durante o dia, inclua proteção solar adequada com orientação profissional.</p></div></div></div></section><section class="shell section rule"><div class="grid g2"><div><span class="eyebrow">Transparência faz parte</span><h2>Vamos<br><span class="serif italic">conversar?</span></h2></div>'''+faq([('Os produtos estão à venda?','Não. Aurora é uma marca fictícia criada para este portfólio. Não há estoque, cobrança ou envio de produtos.'),('As fórmulas possuem comprovação?','As embalagens e descrições são estudos conceituais. Não representam fórmulas reais, certificações ou resultados clínicos.'),('O quiz substitui uma avaliação profissional?','Não. Ele demonstra uma interação de personalização por preferência de horário, sem analisar condições da pele ou indicar tratamento.')])+'''</div></section><section class="closing"><div class="shell"><span class="eyebrow">O essencial está nos detalhes</span><h2>Reserve um tempo<br><span class="serif italic">para você.</span></h2><a class="btn" href="#colecao">Revisitar a coleção ↗</a></div></section></main><dialog class="dialog" id="product-dialog"><button class="dialog-close" data-close aria-label="Fechar produto">×</button><span class="eyebrow">Coleção conceitual</span><h2 id="product-name"></h2><p id="product-description"></p><p class="fine">Produto fictício. Sem compra, alegações clínicas ou recomendação de tratamento.</p><button class="btn" data-close>Continuar explorando ↗</button></dialog>'''+footer('aurora ✳'))
put('aurora/style.css',''':root{--paper:#faf9f2;--ink:#3e492f;--accent:#4d603b;--line:#d8ddc9;--muted:#757d68;--soft:#e8eddb}.brand{font-family:Georgia,serif;font-weight:400;font-size:35px}.sun{font:23px Arial;margin-left:4px}.btn{border-radius:50px}.hero{background:#eeefdf}.hero-layout{display:grid;grid-template-columns:1fr 1fr;min-height:680px;gap:40px;align-items:center}.hero-copy{padding:70px 0}.hero h1{font-size:clamp(3.8rem,6.5vw,6.2rem)}.hero .lead{margin-top:30px;max-width:36ch;font-size:16px}.hero-art{height:640px;position:relative;align-self:end}.hero-art img{border-radius:220px 220px 0 0;object-position:48% 50%}.art-tag{position:absolute;bottom:30px;left:25px;right:25px;background:#faf9f2e8;display:flex;align-items:center;justify-content:space-between;padding:20px 25px;border-radius:12px}.art-tag .serif{font-size:23px;line-height:1.2}.art-tag>span:last-child{font-size:40px}.text-link{align-self:center;font-size:12px;text-decoration:underline;text-underline-offset:5px}.hero-notes{display:flex;flex-wrap:wrap;gap:15px;font-size:10px;margin-top:42px;color:var(--muted)}.hero-notes span:before{content:'·';margin-right:8px}.ticker{display:flex;justify-content:space-around;gap:20px;padding:24px;background:#dce2c9;font:20px Georgia,serif}.product-art{height:360px;position:relative;display:flex;align-items:end;justify-content:center;padding:50px 10px;background:#e8eadc;overflow:hidden;border-radius:170px 170px 10px 10px}.product-art>.pill{position:absolute;top:25px;left:25px;background:#faf9f299}.serum{background:#efdfc9}.cream{background:#e8e3d7}.bottle,.dropper,.jar{display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:18px 20px 20px #3a452026;position:relative}.bottle{width:125px;height:225px;background:linear-gradient(90deg,#778353,#a8b183,#788553);border-radius:25px}.bottle:before{content:'';position:absolute;top:-36px;width:80px;height:40px;background:#c4c8aa;border-radius:6px}.bottle span,.dropper span,.jar span{font:25px Georgia;margin-bottom:17px}.bottle small,.dropper small,.jar small{font-size:9px;text-align:center;letter-spacing:1px}.bottle em,.dropper em,.jar em{font:9px Arial;margin-top:15px}.bottle{color:#f5f4e7}.dropper{width:110px;height:175px;background:linear-gradient(90deg,#80562c,#ad8854,#815627);color:#faf2e0;border-radius:12px}.dropper>div{position:absolute;top:-62px;width:45px;height:62px;background:#ddd9c8;border-radius:20px 20px 5px 5px}.jar{width:175px;height:135px;background:#d8ceb5;border-radius:16px}.jar:before{content:'';position:absolute;top:-28px;width:185px;height:38px;border-radius:10px;background:#606b47}.product-title{display:flex;justify-content:space-between;align-items:center;margin:24px 0 9px}.product-title h3{font:26px Georgia}.product-title>span{font-size:13px}.product>p{font-size:12px;color:var(--muted)}.product-link{border:0;border-bottom:1px solid var(--line);background:none;padding:14px 0;color:var(--ink);font-size:12px}.philosophy{background:#f0efe4}.botanical{position:relative;background:#dfe3cc;min-height:580px;display:flex;align-items:center;justify-content:center;border-radius:200px 200px 0 0;overflow:hidden}.botanical>.serif{font-size:80px;line-height:1;z-index:1;text-align:center}.botanical small{position:absolute;bottom:28px;font-size:10px;letter-spacing:2px}.orb{position:absolute;border:1px solid #81926766;width:400px;height:400px;border-radius:50%}.orb1{top:50px;left:-100px}.orb2{bottom:30px;right:-150px}.philosophy .grid{gap:90px;align-items:center}.philosophy-copy .lead{font-size:16px;margin:28px 0 38px}.principle{display:flex;gap:22px;padding:20px 0;border-top:1px solid var(--line)}.principle>span{font:11px monospace;color:var(--muted)}.principle h3{font-size:17px;margin-bottom:8px}.principle p{font-size:12px;color:var(--muted)}.ritual{border:1px solid var(--line);border-radius:20px;padding:55px;display:grid;grid-template-columns:1fr 1fr;gap:60px}.ritual p{font-size:14px;margin-top:20px}.ritual .fine{font-size:10px}.quiz-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:25px 0}.quiz-options button{border:1px solid var(--line);border-radius:12px;background:transparent;color:var(--ink);padding:20px 5px;font-size:30px}.quiz-options button span{display:block;font-size:10px;margin-top:9px}.quiz-options button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.quiz-result{background:var(--soft);padding:28px;border-radius:12px}.quiz-result .eyebrow{font-size:9px;margin-bottom:12px}.quiz-result h3{font:28px Georgia}.quiz-result p{font-size:12px;margin-top:12px}.closing{text-align:center;background:#dfe5cd;padding:90px 0}.closing .btn{margin-top:35px}@media(max-width:900px){.hero-layout{gap:20px}.philosophy .grid{gap:40px}.ritual{padding:30px;gap:30px}.ticker{font-size:16px}}@media(max-width:650px){.hero-layout{grid-template-columns:1fr;gap:0}.hero-copy{padding:45px 0}.hero-art{height:430px;width:100%}.hero h1{font-size:3.7rem}.ticker{font-size:13px;flex-wrap:wrap}.ticker>span:nth-last-child(-n+2){display:none}.product-art{height:340px}.botanical{min-height:400px}.botanical>.serif{font-size:65px}.ritual{grid-template-columns:1fr;padding:26px}.quiz-options button{padding:18px 5px}.closing{padding:60px 0}}''')
put('aurora/app.js','''const rituals={manha:['Para começar com leveza','Seu começo de dia','Uma limpeza gentil e um momento para hidratar. Durante o dia, inclua proteção solar adequada com orientação profissional.'],noite:['Para desacelerar','Sua pausa à noite','Deixe a correria do lado de fora. Imagine um ritual de limpeza e hidratação, com tempo para perceber as texturas.'],simples:['No seu próprio ritmo','O essencial, sem pressa','Um ritual possível é aquele que cabe no seu dia. Explore os produtos e prefira uma rotina alinhada às suas necessidades com orientação profissional.']};document.querySelectorAll('[data-ritual]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-ritual]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const r=rituals[b.dataset.ritual];['ritual-label','ritual-title','ritual-copy'].forEach((id,i)=>document.getElementById(id).textContent=r[i])}));const products={limpar:['Começo leve','Estudo de embalagem para um gel de limpeza de 150 ml. A paleta oliva e o frasco com válvula traduzem a ideia de um primeiro passo simples. Valor ilustrativo: R$ 59.'],cuidar:['Gota a gota','Estudo de um sérum facial de 30 ml em embalagem âmbar com conta-gotas. O conceito prioriza clareza visual e uma apresentação acolhedora. Valor ilustrativo: R$ 89.'],hidratar:['Toque de calma','Estudo de um creme facial de 50 g em pote reutilizável como intenção de design, sem certificação ambiental ou fórmula real. Valor ilustrativo: R$ 79.']};document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{const p=products[b.dataset.product];document.getElementById('product-name').textContent=p[0];document.getElementById('product-description').textContent=p[1];document.getElementById('product-dialog').showModal()}));''')
# SERRA
put('serra/index.html',head('Serra — Um refúgio no seu ritmo','Pousada conceitual na Mantiqueira. Explore cabanas, experiências e simule sua estadia.','serra')+nav('serra<span class="mountain-mark">△</span>',[('cabanas','As cabanas'),('experiencias','Experiências'),('sobre','O lugar')],'Planejar uma pausa','reserva')+'''<main id="main"><section class="hero"><img class="landscape" src="../assets/serra.svg" alt="Ilustração de cabana entre montanhas e pinheiros ao entardecer" fetchpriority="high"><div class="hero-shade"></div><div class="shell hero-content"><span class="eyebrow">Refúgio conceitual · Serra da Mantiqueira</span><h1>O mundo espera.<br><span class="serif italic">Você pode pausar.</span></h1><p>Uma cabana, o silêncio da serra<br>e tempo para simplesmente estar.</p><a class="btn" href="#cabanas">Encontre seu refúgio ↗</a><div class="hero-caption"><span>22°S · Um lugar imaginado para desacelerar</span><a href="#reserva">Explore a estadia ↓</a></div></div></section><section class="shell booking-wrap" id="reserva"><form id="booking" class="booking"><div class="booking-intro"><span class="eyebrow">Seu próximo respiro</span><h3>Quando vamos?</h3></div><label class="field">Chegada<input type="date" name="checkin" id="checkin" required></label><label class="field">Saída<input type="date" name="checkout" id="checkout" required></label><label class="field">Hóspedes<select name="guests" id="guests"><option value="2">2 pessoas</option><option value="1">1 pessoa</option><option value="3">3 pessoas</option><option value="4">4 pessoas</option></select></label><button class="btn" type="submit">Simular estadia ↗</button><p role="status" class="status" id="booking-result" aria-live="polite"></p><span class="fine booking-note">Simulação com valores fictícios. Nenhuma reserva é realizada.</span></form></section><section class="shell section intro" id="sobre"><span class="eyebrow">Mais perto do que importa</span><h2>Há lugares que você visita.<br>Outros, você <span class="serif italic">sente.</span></h2><div class="intro-copy"><span class="intro-mark">△</span><p class="lead">Serra é um refúgio imaginado entre montanhas, café passado e conversas sem horário. Um convite a trocar a pressa por presença — e a redescobrir o prazer de não fazer nada.</p></div></section><section class="cabins section" id="cabanas"><div class="shell"><div class="section-head"><div><span class="eyebrow">Um abrigo para cada pausa</span><h2>A natureza lá fora.<br><span class="serif italic">O aconchego aqui.</span></h2></div><p class="muted">Escolha entre três conceitos de cabana. Espaços e tarifas fazem parte desta demonstração.</p></div><div class="grid g3"><article class="cabin"><div class="cabin-art"><img src="../assets/serra.svg" alt="Cabana Aurora entre montanhas" loading="lazy"><span class="pill">Para dois</span></div><div class="cabin-copy"><span class="label">01 / AURORA</span><h3>Um novo começo</h3><p>Janela para o nascer do sol, varanda e um canto para o café.</p><ul><li>Até 2 pessoas</li><li>Deck privativo</li><li>Cozinha compacta</li></ul><div class="cabin-bottom"><span>A partir de <strong>R$ 390</strong><small>/ noite · fictício</small></span><button class="round-btn" data-cabin="Aurora" aria-label="Selecionar cabana Aurora">↗</button></div></div></article><article class="cabin"><div class="cabin-art mist"><img src="../assets/serra.svg" alt="Estudo de cabana Neblina" loading="lazy"><span class="pill">Mais espaço</span></div><div class="cabin-copy"><span class="label">02 / NEBLINA</span><h3>Sem olhar o relógio</h3><p>Um refúgio com espaço para ficar, cozinhar e conversar.</p><ul><li>Até 4 pessoas</li><li>Sala integrada</li><li>Varanda com rede</li></ul><div class="cabin-bottom"><span>A partir de <strong>R$ 520</strong><small>/ noite · fictício</small></span><button class="round-btn" data-cabin="Neblina" aria-label="Selecionar cabana Neblina">↗</button></div></div></article><article class="cabin"><div class="cabin-art sunset"><img src="../assets/serra.svg" alt="Estudo de cabana Horizonte" loading="lazy"><span class="pill">Vista aberta</span></div><div class="cabin-copy"><span class="label">03 / HORIZONTE</span><h3>Só mais um pôr do sol</h3><p>Luz de fim de tarde e um horizonte para chamar de seu.</p><ul><li>Até 2 pessoas</li><li>Banheira conceitual</li><li>Deck panorâmico</li></ul><div class="cabin-bottom"><span>A partir de <strong>R$ 590</strong><small>/ noite · fictício</small></span><button class="round-btn" data-cabin="Horizonte" aria-label="Selecionar cabana Horizonte">↗</button></div></div></article></div></div></section><section class="shell section" id="experiencias"><div class="section-head"><div><span class="eyebrow">Sem roteiro obrigatório</span><h2>Pequenas coisas.<br><span class="serif italic">Grandes memórias.</span></h2></div></div><div class="grid g3 experiences"><article><span class="exp-icon">☕</span><h3>Café sem pressa</h3><p>Pão quentinho, café coado e o dia começando no seu tempo.</p><span class="label">Sabores da manhã</span></article><article><span class="exp-icon">↟</span><h3>Caminhos verdes</h3><p>Uma caminhada leve, a sombra das árvores e um novo ponto de vista.</p><span class="label">Natureza por perto</span></article><article><span class="exp-icon">☾</span><h3>Noite de céu aberto</h3><p>Apague as telas. Deixe o brilho do céu ocupar o seu olhar.</p><span class="label">Tempo de contemplar</span></article></div></section><section class="shell section rule"><div class="grid g2"><div><span class="eyebrow">Prepare sua pausa</span><h2>Antes de<br><span class="serif italic">arrumar as malas.</span></h2></div>'''+faq([('A pousada existe?','Não. Serra é uma marca fictícia e as cabanas são ilustrações autorais. Esta página demonstra a experiência digital de uma hospedagem.'),('A simulação confirma disponibilidade?','Não. O simulador calcula noites e tarifas ilustrativas. Não consulta calendário, não cobra e não realiza reservas.'),('Como os valores são calculados?','Aurora: R$ 390/noite para até 2 pessoas; Neblina: R$ 520/noite para até 4; Horizonte: R$ 590/noite para até 2. Na seleção automática, grupos de 3 ou 4 pessoas usam a Neblina.'),('Posso enviar meus dados para reservar?','Esta demonstração não coleta dados de contato. Em um projeto real, o fluxo poderia ser conectado a um motor de reservas ou atendimento.')])+'''</div></section><section class="slow"><div class="shell"><span class="eyebrow">Menos notificações. Mais natureza.</span><h2>Sua próxima pausa<br><span class="serif italic">começa com uma escolha.</span></h2><a class="btn" href="#reserva">Planejar minha estadia ↗</a></div></section></main>'''+footer('serra △'))
put('serra/style.css',''':root{--paper:#f5f2e9;--ink:#253e31;--accent:#d3aa6c;--button-ink:#243b2e;--line:#d5d9ca;--muted:#717d6d;--soft:#e6eadb}.brand{font:36px Georgia;letter-spacing:-2px}.mountain-mark{font:30px Arial;margin-left:2px}.nav .btn{background:#304936;color:#f5f2e9}.hero{height:690px;position:relative;color:#fcf5e4}.landscape,.hero-shade{position:absolute;inset:0;width:100%;height:100%}.landscape{object-position:center 60%}.hero-shade{background:linear-gradient(90deg,#0e291bd9,#16342560 70%)}.hero-content{position:relative;padding-top:95px;height:100%}.hero h1{font-size:clamp(3.6rem,6.2vw,6.5rem)}.hero p{margin:28px 0;font-size:17px;color:#e4e8d5}.hero-caption{position:absolute;bottom:75px;left:0;right:0;display:flex;justify-content:space-between;font-size:10px;letter-spacing:.1em}.hero-caption a{font-size:11px}.booking-wrap{position:relative;margin-top:-45px}.booking{background:var(--paper);padding:30px;display:grid;grid-template-columns:1.2fr 1fr 1fr .8fr 1.15fr;gap:20px;align-items:center;box-shadow:0 10px 40px #21392212}.booking-intro .eyebrow{font-size:8px;margin-bottom:12px}.booking-intro h3{font:27px Georgia}.booking .field{font-size:10px}.booking .btn{align-self:end;min-height:49px}.booking-note{grid-column:1/-1;text-align:right;font-size:9px}.booking .status{grid-column:1/-1;margin:0}.intro{text-align:center;padding-top:120px}.intro h2{font-size:clamp(2.6rem,4.3vw,4.6rem)}.intro-copy{display:flex;align-items:center;justify-content:center;gap:65px;margin:40px auto 0;max-width:800px;text-align:left}.intro-mark{font:90px Georgia;color:#9b9d78}.intro-copy p{font-size:16px}.cabins{background:#e8ebdf}.cabin{background:var(--paper)}.cabin-art{height:275px;position:relative;overflow:hidden}.cabin-art img{object-position:50% 65%;transform:scale(1.2)}.cabin-art .pill{position:absolute;top:18px;left:18px;background:#faf5e6e6;border:0}.mist img{filter:saturate(.4) brightness(1.13)}.sunset img{filter:sepia(.35) saturate(1.2)}.cabin-copy{padding:28px}.cabin h3{font:30px Georgia;margin:14px 0}.cabin p{font-size:13px;color:var(--muted)}.cabin ul{padding:18px 0;list-style:none;font-size:11px;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:9px}.cabin ul li:before{content:'·';margin-right:5px}.cabin-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:25px}.cabin-bottom span{font-size:10px}.cabin-bottom strong{display:block;font:27px Georgia}.cabin-bottom small{font-size:9px}.round-btn{width:45px;height:45px;border:1px solid var(--line);border-radius:50%;background:transparent;color:inherit;font-size:20px}.experiences article{padding:30px;border-left:1px solid var(--line)}.exp-icon{font-size:45px;display:block;margin-bottom:30px}.experiences h3{font:28px Georgia}.experiences p{font-size:14px;color:var(--muted);margin:20px 0 30px}.experiences .label{font-size:9px}.slow{text-align:center;padding:100px 0;background:#253e31;color:#f1eedf}.slow .btn{margin-top:36px}@media(max-width:900px){.booking{grid-template-columns:1fr 1fr}.booking-intro{grid-column:1/-1}.booking .btn{grid-column:auto}.hero-caption{left:0}.cabin-copy{padding:22px}}@media(max-width:650px){.hero{height:620px}.hero-content{padding-top:65px}.hero h1{font-size:3.5rem}.hero-caption{bottom:70px}.hero-caption a{display:none}.hero-caption>span{font-size:8px}.booking{padding:24px;gap:16px}.booking .btn{grid-column:1/-1}.booking-note{text-align:left}.booking-wrap{margin-top:-35px}.intro{padding-top:65px}.intro-copy{gap:20px;align-items:start}.intro-mark{font-size:50px}.intro-copy p{font-size:14px}.experiences article{border-left:0;border-top:1px solid var(--line);padding:28px 0}.slow{padding:65px 0}.cabin-art{height:300px}}''')
put('serra/app.js','''const form=document.getElementById('booking'),arrival=document.getElementById('checkin'),departure=document.getElementById('checkout'),guests=document.getElementById('guests'),result=document.getElementById('booking-result');const today=new Date();const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;arrival.min=localDate(today);let chosen=null;const cabins={Aurora:{rate:390,max:2},Neblina:{rate:520,max:4},Horizonte:{rate:590,max:2}};arrival.addEventListener('change',()=>{const d=new Date(arrival.value+'T12:00:00');d.setDate(d.getDate()+1);departure.min=localDate(d);if(departure.value&&departure.value<=arrival.value)departure.value='';result.textContent=''});guests.addEventListener('change',()=>{if(chosen&&Number(guests.value)>cabins[chosen].max)chosen=null;result.textContent=''});form.addEventListener('submit',e=>{e.preventDefault();const nights=(Date.parse(departure.value+'T12:00:00Z')-Date.parse(arrival.value+'T12:00:00Z'))/86400000;if(!(nights>0&&nights<=30)){result.textContent='Escolha uma saída após a chegada, com até 30 noites.';return}const name=chosen|| (Number(guests.value)>2?'Neblina':'Aurora');const price=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(nights*cabins[name].rate);result.textContent=`Simulação: ${nights} ${nights===1?'noite':'noites'} · ${name} · ${guests.value} ${guests.value==='1'?'pessoa':'pessoas'} · Total ilustrativo ${price}. Sem consulta de disponibilidade, taxas extras ou reserva real.`});document.querySelectorAll('[data-cabin]').forEach(b=>b.addEventListener('click',()=>{chosen=b.dataset.cabin;if(Number(guests.value)>cabins[chosen].max)guests.value=String(cabins[chosen].max);result.textContent=`Cabana ${chosen} selecionada. Informe as datas para simular.`;document.getElementById('reserva').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});arrival.focus({preventScroll:true})}));''')
# FLUXO
put('fluxo/index.html',head('Fluxo — Menos caos, mais trabalho feito','Landing page conceitual de um software para organizar projetos, tarefas e equipes.','fluxo')+nav('<span class="logo-box">ƒ</span>fluxo',[('produto','Produto'),('como-funciona','Como funciona'),('planos','Planos')],'Explorar a demo','demo')+'''<main id="main"><section class="shell hero"><div class="hero-copy"><span class="version"><i></i> Seu trabalho, em movimento · conceito v1.0</span><h1>Seu time no mesmo ritmo.<br><span>Seu trabalho em fluxo.</span></h1><p class="lead">Projetos, prazos e prioridades em um só lugar.<br>Menos “como está aquilo?”. Mais clareza para fazer acontecer.</p><div class="actions"><a class="btn" href="#demo">Explorar demo interativa <span>→</span></a><a class="btn light" href="#planos">Conhecer os planos</a></div><p class="hero-fine">Sem cadastro. Sem cartão. Uma experiência demonstrativa.</p></div><div class="app-window" id="demo"><div class="window-top"><span><i></i><i></i><i></i></span><span>app.fluxo.demo / projetos / lançamento</span><span>DEMO</span></div><div class="app-layout"><aside class="sidebar"><div class="workspace-avatar">F</div><span>◫</span><span class="active">▦</span><span>◷</span><span>⚙</span><span class="sidebar-bottom">GS</span></aside><div class="app-main"><div class="app-toolbar"><div><span class="label">Workspace / Marketing</span><h3>Lançamento da marca <span>✳</span></h3></div><span class="avatars"><i>AM</i><i>LC</i><i>GS</i></span></div><div class="app-tabs"><span class="selected">▦ Quadro</span><span>☷ Visão do projeto</span><span class="app-hint">Mova as tarefas pelos botões →</span></div><div class="board" id="board"></div><p class="board-status" id="board-status" aria-live="polite">Experimente mover uma tarefa para a próxima etapa.</p></div></div></div><div class="under-app"><span>Uma visão compartilhada.</span><span>Prioridades visíveis.</span><span>Próximos passos claros.</span></div></section><section class="shell section" id="produto"><div class="section-head"><div><span class="eyebrow">Não é sobre fazer mais</span><h2>É sobre saber<br><span class="highlight">o que importa agora.</span></h2></div><p class="muted">Uma interface pensada para tirar o trabalho da conversa e colocá-lo em movimento.</p></div><div class="features"><article class="feature-large"><span class="feature-icon">▦</span><h3>Do “precisamos fazer”<br>ao “está pronto”.</h3><p>Organize cada entrega em etapas visíveis. O time sabe onde está, o que falta e quem está cuidando.</p><div class="mini-flow"><span>A fazer <b>3</b></span><span>Em andamento <b>2</b></span><span>Concluído <b>5</b></span></div></article><article><span class="feature-icon">◎</span><h3>Prioridade sem ruído</h3><p>Uma hierarquia clara para diferenciar o urgente do que pode esperar.</p><div class="priority-example"><span>● Alta</span> Revisar entrega principal</div></article><article><span class="feature-icon">◷</span><h3>Mais contexto.<br>Menos reuniões.</h3><p>Concentre informações da entrega em um espaço compreensível por todos.</p><div class="context-example"><span>GS</span><p>Revisão pronta para o próximo passo.<small>Comentário ilustrativo · agora</small></p></div></article></div></section><section class="how section" id="como-funciona"><div class="shell"><span class="eyebrow">Clareza em três movimentos</span><h2>Comece simples.<br>Continue <span class="highlight">organizado.</span></h2><div class="grid g3 how-grid"><article><span class="step-no">01</span><h3>Crie um projeto</h3><p>Defina o objetivo e organize o que precisa ser entregue.</p></article><article><span class="step-no">02</span><h3>Distribua os próximos passos</h3><p>Transforme grandes ideias em tarefas com responsáveis.</p></article><article><span class="step-no">03</span><h3>Acompanhe o movimento</h3><p>Visualize o progresso e ajuste a rota antes do prazo.</p></article></div></div></section><section class="shell section" id="planos"><div class="section-head"><div><span class="eyebrow">Espaço para o seu momento</span><h2>Um plano para<br><span class="highlight">cada fase.</span></h2></div><div><div class="billing" role="group" aria-label="Ciclo de pagamento"><button data-billing="monthly" aria-pressed="true">Mensal</button><button data-billing="yearly" aria-pressed="false">Anual <small>−20%</small></button></div><p class="fine" style="margin-top:10px">Preços fictícios · sem contratação</p></div></div><div class="grid g3 pricing"><article><span class="label">Essencial</span><h3>Para começar</h3><div class="price">R$ 0<span>/ pessoa / mês</span></div><p>Uma primeira visão do trabalho.</p><ul><li>Até 2 projetos ilustrativos</li><li>Quadro de tarefas</li><li>Visão de prioridades</li></ul><button class="btn light" data-plan="Essencial">Explorar Essencial →</button></article><article class="featured"><span class="plan-badge">PARA TIMES EM MOVIMENTO</span><span class="label">Equipe</span><h3>Para conectar</h3><div class="price">R$ <b data-price="29">29</b><span>/ pessoa / mês</span></div><p>Clareza compartilhada no dia a dia.</p><ul><li>Projetos sem limite no conceito</li><li>Responsáveis e datas</li><li>Visão de progresso</li><li>Comentários e contexto</li></ul><button class="btn" data-plan="Equipe">Explorar Equipe →</button><p class="fine annual-note" hidden>R$ 278,40 por pessoa/ano · equivalente a R$ 23,20/mês</p></article><article><span class="label">Estúdio</span><h3>Para expandir</h3><div class="price">R$ <b data-price="49">49</b><span>/ pessoa / mês</span></div><p>Uma visão ampla de cada frente.</p><ul><li>Tudo do plano Equipe</li><li>Visão de múltiplos projetos</li><li>Modelos de processo</li><li>Painel de acompanhamento</li></ul><button class="btn light" data-plan="Estúdio">Explorar Estúdio →</button><p class="fine annual-note" hidden>R$ 470,40 por pessoa/ano · equivalente a R$ 39,20/mês</p></article></div><p class="fine" style="margin-top:20px">Recursos representam o conceito do produto. Esta landing page não é um software de gestão completo.</p></section><section class="shell section rule"><div class="grid g2"><div><span class="eyebrow">Sem pontas soltas</span><h2>Alguma<br><span class="highlight">dúvida?</span></h2></div>'''+faq([('Posso usar o Fluxo no meu time?','Fluxo é um produto fictício criado para demonstrar uma landing page de SaaS. A área interativa é uma simulação local de movimentação de tarefas.'),('As tarefas ficam salvas?','Não. O quadro funciona apenas na sessão atual e volta ao estado inicial ao recarregar a página. Nenhuma informação é enviada.'),('O plano anual é cobrado como?','Na simulação, o desconto de 20% é aplicado sobre 12 mensalidades. Os equivalentes mensais e os totais anuais aparecem juntos para deixar o conceito claro.'),('Existe cadastro ou cobrança?','Não. Os botões de plano abrem apenas uma explicação demonstrativa, sem cadastro, cartão ou assinatura.')])+'''</div></section><section class="cta"><div class="shell"><span class="eyebrow">Menos abas. Mais direção.</span><h2>Seu próximo projeto<br>merece <span class="highlight">mais clareza.</span></h2><a class="btn" href="#demo">Experimentar o quadro →</a></div></section></main><dialog class="dialog" id="plan-dialog"><button class="dialog-close" data-close aria-label="Fechar plano">×</button><span class="eyebrow">Explorando possibilidades</span><h2 id="plan-title"></h2><p id="plan-copy"></p><p class="fine">Não há contratação. Recursos e preços são fictícios.</p><button class="btn" data-close>Entendi, continuar →</button></dialog>'''+footer('ƒ fluxo'))
put('fluxo/style.css',''':root{--paper:#f9fbfa;--ink:#182d28;--accent:#c4f56b;--button-ink:#182d28;--muted:#6b7c75;--line:#dce5de;--soft:#e8f3de}.brand{font-size:30px}.logo-box{background:var(--accent);font:italic bold 34px Georgia;width:35px;height:35px;display:grid;place-items:center;border-radius:9px}.btn{border-radius:8px;font-size:12px}.hero{padding-top:66px}.hero-copy{text-align:center}.version{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);padding:7px 12px;border-radius:40px;font-size:10px}.version i{width:6px;height:6px;background:#6aab35;border-radius:50%}.hero h1{margin:27px 0;font-size:clamp(3rem,5.4vw,5.5rem);font-weight:600;letter-spacing:-.06em}.hero h1>span{color:#708178}.hero .lead{margin:auto;font-size:16px}.hero .actions{justify-content:center}.hero-fine{margin:15px auto 40px;font-size:10px;color:var(--muted)}.app-window{border:1px solid #cbd6ce;border-radius:14px;background:white;overflow:hidden;box-shadow:0 30px 70px #21392c12;text-align:left}.window-top{background:#edf2ed;display:flex;align-items:center;justify-content:space-between;padding:14px 20px;font-size:9px;color:#6a7e6c;border-bottom:1px solid var(--line)}.window-top>span:first-child{display:flex;gap:5px}.window-top i{display:block;width:7px;height:7px;background:#c5d1c2;border-radius:50%}.app-layout{display:grid;grid-template-columns:65px 1fr}.sidebar{background:#f0f4ee;border-right:1px solid var(--line);padding:20px 12px;display:flex;flex-direction:column;gap:22px;align-items:center;font-size:20px;color:#78917e}.workspace-avatar{background:#203c30;color:#daf0b7;width:30px;height:30px;display:grid;place-items:center;border-radius:8px;font-size:16px}.sidebar>.active{background:#d9e9cb;color:#325231;width:32px;text-align:center;border-radius:7px}.sidebar-bottom{margin-top:auto;font-size:11px;background:#e5cdb2;border-radius:50%;padding:6px}.app-main{padding:28px;min-width:0}.app-toolbar{display:flex;justify-content:space-between;gap:20px;align-items:center}.app-toolbar .label{font-size:8px;color:var(--muted)}.app-toolbar h3{font-size:24px;font-weight:600;margin-top:9px}.app-toolbar h3>span{font-size:18px;color:#91ad79}.avatars{display:flex}.avatars i{font:9px Arial;border-radius:50%;padding:8px;border:2px solid white;background:#d7e6cb;margin-left:-5px}.avatars i:nth-child(2){background:#e8d9c0}.avatars i:nth-child(3){background:#cddbe7}.app-tabs{display:flex;gap:25px;font-size:10px;border-bottom:1px solid var(--line);padding:23px 0 15px;margin-bottom:22px;color:var(--muted)}.selected{color:#203d2d}.app-hint{margin-left:auto;font-size:9px}.board{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.board-column{background:#f3f6f0;padding:15px;border-radius:8px;min-height:255px}.column-title{display:flex;justify-content:space-between;align-items:center;font-size:10px;margin-bottom:15px}.column-title b{background:#e2e9dd;font-size:9px;border-radius:4px;padding:2px 6px;font-weight:400}.task{background:white;border:1px solid #dce4d8;border-radius:7px;padding:14px;margin-top:10px;box-shadow:0 2px 3px #30412c05}.task>span{font-size:8px;color:#746d52;background:#f8ecd3;padding:3px 7px;border-radius:4px}.task h4{font-size:11px;margin:12px 0 17px;font-weight:500}.task-bottom{display:flex;justify-content:space-between;align-items:center;font-size:8px;color:var(--muted)}.task button{border:1px solid var(--line);border-radius:4px;background:#f0f6e8;padding:3px 8px;color:#314c31}.board-status{font-size:10px;color:var(--muted);margin-top:18px}.under-app{display:flex;justify-content:center;gap:65px;margin:25px 0;font-size:11px;color:var(--muted)}.highlight{color:#739154}.features{display:grid;grid-template-columns:1fr 1fr;gap:20px}.features article{background:#eff4eb;border:1px solid #e2e9db;border-radius:16px;padding:38px}.features .feature-large{grid-row:span 2;background:#e0edcc;display:flex;flex-direction:column;justify-content:center}.feature-icon{display:inline-block;font-size:30px;margin-bottom:24px}.features h3{font-size:28px;font-weight:600;line-height:1.2;margin-bottom:18px}.features p{font-size:13px;color:var(--muted)}.feature-large h3{font-size:38px}.mini-flow{display:flex;gap:10px;margin-top:55px;transform:rotate(-3deg)}.mini-flow>span{padding:20px 12px;background:#ffffffa8;border:1px solid #c6d8af;border-radius:8px;font-size:9px;flex:1}.mini-flow b{display:block;font-size:28px;margin-top:10px;font-weight:500}.priority-example{background:white;padding:16px;border-radius:8px;margin-top:25px;font-size:11px}.priority-example span{font-size:9px;color:#a34a35;margin-right:10px}.context-example{display:flex;gap:12px;margin-top:25px;background:#fff;padding:16px;border-radius:8px}.context-example>span{border-radius:50%;background:#dfebce;padding:8px;font-size:10px;height:32px}.context-example p{font-size:10px}.context-example small{display:block;font-size:8px;margin-top:7px}.how{background:#18382b;color:#f5f9ed}.how .highlight{color:#c4f56b}.how-grid{margin-top:60px;gap:40px}.step-no{display:block;font-size:35px;color:#b5cf9a;border-bottom:1px solid #49614d;padding-bottom:25px;margin-bottom:25px}.how h3{font-size:22px;margin-bottom:16px}.how p{font-size:13px;color:#b5c7b5}.billing{border:1px solid var(--line);border-radius:40px;padding:4px;display:flex;gap:4px}.billing button{border:0;background:transparent;padding:10px 20px;border-radius:30px;color:var(--ink);font-size:12px}.billing button[aria-pressed=true]{background:var(--ink);color:var(--paper)}.billing small{font-size:9px;color:#86ac60;margin-left:5px}.pricing article{position:relative;border:1px solid var(--line);border-radius:14px;padding:35px;display:flex;flex-direction:column}.pricing .featured{border:2px solid #91b16f;background:#f1f7e9}.plan-badge{position:absolute;top:-14px;left:20px;background:#c4f56b;padding:7px 15px;border-radius:20px;font-size:8px;letter-spacing:.1em}.pricing h3{font-size:25px;margin-top:18px}.price{font-size:43px;line-height:1.3;margin:25px 0}.price>b{font-weight:400}.price span{display:block;font-size:10px;color:var(--muted);margin-top:5px}.pricing article>p{font-size:12px;color:var(--muted)}.pricing ul{padding:20px 0 32px;list-style:none;font-size:12px;margin:0}.pricing li{margin-top:12px}.pricing li:before{content:'✓';margin-right:12px;color:#668249}.pricing .btn{margin-top:auto;width:100%}.pricing .annual-note{font-size:9px;margin-top:16px}.cta{text-align:center;background:#edf3e5;padding:90px 0}.cta .btn{margin-top:34px}@media(max-width:900px){.app-main{padding:20px}.board{gap:10px}.board-column{padding:10px}.app-hint{display:none}.pricing article{padding:25px}.under-app{gap:25px}}@media(max-width:650px){.hero{padding-top:40px}.hero h1{font-size:3.1rem}.hero .lead{font-size:14px}.app-layout{grid-template-columns:1fr}.sidebar{display:none}.app-main{padding:16px}.app-toolbar h3{font-size:18px}.app-tabs{gap:17px;font-size:9px}.window-top{padding:12px}.window-top>span:nth-child(2){font-size:7px}.board{grid-template-columns:1fr}.board-column{min-height:unset}.task{padding:14px}.task h4{font-size:13px}.task-bottom{font-size:10px}.task button{padding:5px 12px}.column-title{font-size:12px}.under-app{flex-direction:column;gap:7px;align-items:center}.features{grid-template-columns:1fr}.features .feature-large{grid-row:auto}.features article{padding:28px}.feature-large h3{font-size:31px}.mini-flow{margin-top:35px;gap:6px}.mini-flow>span{padding:15px 8px}.pricing{gap:30px}.cta{padding:65px 0}.board-status{font-size:11px}.version{font-size:9px}}''')
put('fluxo/app.js','''const tasks=[{id:1,title:'Definir narrativa da marca',tag:'Estratégia',owner:'AM',step:0},{id:2,title:'Criar direção visual',tag:'Design',owner:'LC',step:0},{id:3,title:'Desenvolver landing page',tag:'Produto',owner:'GS',step:1},{id:4,title:'Organizar referências',tag:'Pesquisa',owner:'AM',step:2}];const names=['A fazer','Em andamento','Concluído'];function draw(){const board=document.getElementById('board');board.replaceChildren();names.forEach((name,i)=>{const col=document.createElement('section');col.className='board-column';col.setAttribute('aria-label',name);const title=document.createElement('div');title.className='column-title';title.textContent=name+' ';const count=document.createElement('b');count.textContent=tasks.filter(t=>t.step===i).length;title.append(count);col.append(title);tasks.filter(t=>t.step===i).forEach(t=>{const card=document.createElement('article');card.className='task';const tag=document.createElement('span');tag.textContent=t.tag;const h=document.createElement('h4');h.textContent=t.title;const bottom=document.createElement('div');bottom.className='task-bottom';const owner=document.createElement('span');owner.textContent=t.owner+' · Exemplo';const b=document.createElement('button');b.textContent=i===2?'↶':'→';b.setAttribute('aria-label',i===2?'Reabrir '+t.title:'Avançar '+t.title+' para '+names[i+1]);b.addEventListener('click',()=>{t.step=(t.step+1)%3;draw();document.getElementById('board-status').textContent=t.title+' movida para '+names[t.step]+'. Alteração apenas nesta demo.';document.querySelector(`[data-task="${t.id}"] button`).focus()});card.dataset.task=t.id;bottom.append(owner,b);card.append(tag,h,bottom);col.append(card)});board.append(col)})}draw();let yearly=false;document.querySelectorAll('[data-billing]').forEach(b=>b.addEventListener('click',()=>{yearly=b.dataset.billing==='yearly';document.querySelectorAll('[data-billing]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-price]').forEach(x=>x.textContent=yearly?(Number(x.dataset.price)*.8).toFixed(2).replace('.',','):x.dataset.price);document.querySelectorAll('.annual-note').forEach(x=>x.hidden=!yearly)}));document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('plan-title').textContent='Plano '+b.dataset.plan;document.getElementById('plan-copy').textContent='Você explorou o plano '+b.dataset.plan+' no ciclo '+(yearly?'anual':'mensal')+'. Em um produto real, este ponto iniciaria o cadastro. Nesta experiência, você pode testar o quadro de tarefas sem criar conta.';document.getElementById('plan-dialog').showModal()}));''')
# BRASA
put('brasa/index.html',head('Brasa — Pizza de verdade, sem pressa','Pizzaria conceitual. Explore sabores e monte um pedido demonstrativo.','brasa')+nav('brasa<span>®</span>',[('cardapio','Cardápio'),('historia','Nossa massa'),('como-pedir','Como pedir')],'Montar meu pedido','cardapio')+'''<main id="main"><section class="hero"><div class="shell hero-layout"><div class="hero-copy"><span class="eyebrow">Massa leve · Forno quente · Mesa cheia</span><h1>A noite pede<br><span class="serif italic">uma boa pizza.</span></h1><p>Uma massa feita com tempo.<br>Ingredientes escolhidos com cuidado.<br>E aquele último pedaço que vira disputa.</p><div class="actions"><a class="btn" href="#cardapio">Escolher meu sabor ↗</a><span class="hero-stamp">Feita para<br><b>compartilhar.</b></span></div><span class="hero-small">Marca fictícia · Pedidos apenas demonstrativos</span></div><div class="pizza-art"><img src="../assets/pizza.svg" alt="Ilustração autoral de pizza com queijo, tomate e manjericão" fetchpriority="high"><span class="pizza-tag">Boa companhia.<br><i>Melhor ainda.</i></span></div></div></section><div class="marquee"><span>FERMENTAÇÃO LENTA</span><b>✳</b><span>RECEITA DA CASA</span><b>✳</b><span>DO FORNO PRA MESA</span><b>✳</b><span>MAIS UM PEDAÇO?</span></div><section class="shell section" id="cardapio"><div class="section-head"><div><span class="eyebrow">Tem um sabor com seu nome</span><h2>Escolha bem.<br><span class="serif italic">Repita sem culpa.</span></h2></div><p class="muted">Pizzas de 35 cm, 8 fatias.<br>Valores e ingredientes ilustrativos. Este site não realiza vendas.</p></div><div class="menu-controls"><div class="chips" role="group" aria-label="Filtrar cardápio"><button class="chip" data-menu="all" aria-pressed="true">Todas</button><button class="chip" data-menu="classicas" aria-pressed="false">As clássicas</button><button class="chip" data-menu="autorais" aria-pressed="false">Da casa</button><button class="chip" data-menu="vegetarianas" aria-pressed="false">Sem carne</button></div><button class="cart-trigger" data-dialog="cart-dialog">Seu pedido <span id="cart-count">0</span> ↗</button></div><div class="grid g3 menu-grid" id="menu-grid"></div><p class="fine" style="margin-top:24px">Alergênicos ilustrativos: as pizzas contêm trigo e leite. Não há operação real nem garantia de ausência de contaminação cruzada.</p></section><section class="story" id="historia"><div class="shell section grid g2"><div class="story-art"><div class="dough-circle"><span class="serif">O ingrediente<br>que não dá<br>para acelerar?<br><i>Tempo.</i></span></div><span class="label">Uma boa história começa na massa.</span></div><div class="story-copy"><span class="eyebrow">Do primeiro gesto ao último pedaço</span><h2>A gente acredita<br><span class="serif italic">no simples bem feito.</span></h2><p class="lead">Brasa nasceu como uma ideia: transformar uma pizza em um convite para estar junto. Sem cerimônia. Sem complicar.</p><p>Na narrativa desta marca conceitual, a massa descansa, o molho tem protagonismo e o forno termina o que o tempo começou.</p><div class="story-details"><div><span>01</span><h3>Tempo de massa</h3><p>Leveza como ponto de partida.</p></div><div><span>02</span><h3>Calor na medida</h3><p>Borda dourada, centro macio.</p></div><div><span>03</span><h3>Mesa compartilhada</h3><p>A melhor parte vem depois.</p></div></div></div></div></section><section class="shell section" id="como-pedir"><div class="section-head"><div><span class="eyebrow">Do desejo ao primeiro pedaço</span><h2>Uma noite boa<br><span class="serif italic">começa fácil.</span></h2></div></div><div class="grid g3 order-steps"><article><span>01</span><h3>Encontre seu sabor</h3><p>Explore as clássicas ou descubra as combinações da casa.</p></article><article><span>02</span><h3>Monte a mesa</h3><p>Adicione pizzas ao pedido e ajuste as quantidades.</p></article><article><span>03</span><h3>Confira tudo</h3><p>Veja o resumo e simule a finalização. Sem envio ou pagamento.</p></article></div></section><section class="shell section rule"><div class="grid g2"><h2>Antes de<br><span class="serif italic">pedir mais.</span></h2>'''+faq([('Consigo fazer um pedido de verdade?','Não. Brasa é uma pizzaria fictícia. O carrinho é uma demonstração local e não envia informações, não cobra e não gera entrega.'),('Quais tamanhos estão disponíveis?','O cardápio demonstrativo usa um tamanho único de 35 cm, com 8 fatias. Não há opção de meia pizza nesta versão.'),('O total inclui entrega?','Não há serviço de entrega. O total representa apenas a soma dos produtos ilustrativos, sem cobrança.'),('Meu pedido fica salvo?','Não. As escolhas permanecem apenas enquanto esta página está aberta e são apagadas ao recarregar.')])+'''</div></section><section class="pizza-cta"><div class="shell"><span class="eyebrow">Tem lugar pra mais um</span><h2>Chama a turma.<br><span class="serif italic">O sabor a gente resolve.</span></h2><a class="btn" href="#cardapio">Vamos de pizza ↗</a></div></section></main><dialog class="dialog" id="cart-dialog"><button class="dialog-close" data-close aria-label="Fechar pedido">×</button><span class="eyebrow">Só falta escolher a companhia</span><h2>Seu pedido.</h2><div id="cart-items"></div><div class="cart-total"><span>Total ilustrativo</span><strong id="cart-total">R$ 0,00</strong></div><p class="fine">Demonstração local. Sem entrega, pagamento ou transmissão de dados.</p><button class="btn" id="checkout">Simular finalização ↗</button><p class="status" role="status" id="checkout-status" aria-live="polite"></p></dialog><div class="toast" role="status" id="toast" aria-live="polite"></div>'''+footer('brasa®'))
put('brasa/style.css',''':root{--paper:#f8f1df;--ink:#293d2e;--accent:#b94128;--button-ink:#fff6e7;--line:#d8d3bc;--muted:#797e69;--soft:#e9e8ce}.brand{font:bold 38px Georgia;letter-spacing:-2px}.brand>span{font:12px Arial;align-self:start;margin-top:6px}.btn{border-radius:4px}.hero{background:#203c2e;color:#f8f0d9}.hero-layout{display:grid;grid-template-columns:1fr 1fr;align-items:center;min-height:660px;gap:20px}.hero-copy{padding:70px 0;z-index:1}.hero h1{font-size:clamp(3.8rem,6.4vw,6.6rem)}.hero p{font-size:16px;margin:32px 0;color:#cfd6ba}.hero-stamp{font-size:11px;line-height:1.4;transform:rotate(-10deg);border:1px solid #809271;padding:15px 20px;border-radius:50%;margin-left:12px;align-self:center}.hero-small{display:block;font-size:9px;color:#b6c2a8;margin-top:35px}.pizza-art{height:620px;position:relative;overflow:hidden}.pizza-art img{object-fit:cover;object-position:50% 50%;border-radius:50%;transform:rotate(-9deg) scale(1.06)}.pizza-tag{position:absolute;right:0;bottom:35px;background:#f8f1df;color:var(--ink);padding:20px 25px;transform:rotate(7deg);font:20px Georgia;line-height:1.25}.marquee{background:#b94128;color:#fff0d2;display:flex;gap:30px;justify-content:space-around;padding:21px 12px;align-items:center;font-size:10px;letter-spacing:.1em}.marquee b{font-size:20px}.menu-controls{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:35px}.cart-trigger{background:#293d2e;color:#fff5e0;padding:12px 18px;border:0;border-radius:4px;font-size:12px;white-space:nowrap}.cart-trigger span{background:#f5edd7;color:#293d2e;border-radius:50%;padding:3px 7px;margin:0 10px}.menu-card{border:1px solid var(--line);padding:20px;background:#fbf6e8}.menu-img{height:215px;overflow:hidden;background:#e4e2ca;position:relative}.menu-img img{transform:scale(1.15);border-radius:50%}.menu-img>.pill{position:absolute;top:12px;left:12px;background:#faf1da;border:0;font-size:8px}.menu-card h3{font:28px Georgia;margin:24px 0 12px}.menu-card p{font-size:12px;color:var(--muted);min-height:58px}.menu-card .allergen{font-size:9px;min-height:0;margin:12px 0 20px}.menu-card-bottom{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:18px}.menu-card-bottom strong{font:26px Georgia}.add{border:0;background:#b94128;color:#fff5e4;font-size:12px;padding:10px 15px;border-radius:3px}.story{background:#e7e7d3}.story .grid{align-items:center;gap:75px}.story-art{text-align:center}.dough-circle{aspect-ratio:1;max-width:480px;background:#d3b68a;border:25px solid #d9c195;box-shadow:inset 0 0 0 3px #c5a878;display:grid;place-items:center;border-radius:50%;margin:auto;transform:rotate(-6deg)}.dough-circle .serif{font-size:50px;line-height:1.1}.dough-circle i{color:#9c482a}.story-art .label{display:block;font-size:9px;margin-top:28px}.story-copy .lead{margin:30px 0 20px;font-size:16px}.story-copy>p:not(.lead){font-size:13px;color:var(--muted)}.story-details{margin-top:35px}.story-details>div{position:relative;border-top:1px solid var(--line);padding:18px 0 18px 40px}.story-details span{position:absolute;left:0;font-size:10px;color:var(--muted)}.story-details h3{font-size:17px;margin-bottom:8px}.story-details p{font-size:11px;color:var(--muted)}.order-steps article{border-top:1px solid var(--line);padding-top:22px}.order-steps article>span{font:40px Georgia;color:#b94128}.order-steps h3{font:29px Georgia;margin:23px 0 15px}.order-steps p{font-size:14px;color:var(--muted)}.pizza-cta{background:#b94128;color:#fff0d5;text-align:center;padding:90px 0}.pizza-cta .btn{margin-top:35px;background:#f6eccf;color:#293d2e}.cart-line{border-bottom:1px solid var(--line);padding:18px 0;display:flex;justify-content:space-between;align-items:center;gap:15px}.cart-line h3{font:22px Georgia;margin-bottom:7px}.cart-line small{font-size:11px;color:var(--muted)}.qty{display:flex;align-items:center;gap:12px}.qty button{border:1px solid var(--line);background:transparent;color:inherit;width:30px;height:30px}.qty span{font-size:12px}.cart-total{display:flex;justify-content:space-between;align-items:center;padding:25px 0;font-size:13px}.cart-total strong{font:28px Georgia}.dialog #checkout{width:100%}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#263d2e;color:#f9efd9;padding:14px 24px;border-radius:5px;font-size:12px;box-shadow:0 4px 25px #0002;z-index:5;max-width:calc(100% - 32px);pointer-events:none}.toast:empty{display:none}@media(max-width:900px){.hero-layout{gap:0}.pizza-art{height:520px}.story .grid{gap:35px}.dough-circle .serif{font-size:38px}.marquee{gap:16px;font-size:8px}}@media(max-width:650px){.hero-layout{grid-template-columns:1fr}.hero-copy{padding:48px 0 15px}.hero h1{font-size:3.8rem}.pizza-art{height:390px;width:100%;margin-top:10px}.pizza-art img{transform:rotate(-9deg) scale(1)}.pizza-tag{right:10px;bottom:15px;font-size:17px}.marquee>span:nth-last-child(-n+2),.marquee>b:last-of-type{display:none}.marquee{font-size:8px;gap:12px}.menu-controls{align-items:start;flex-direction:column}.menu-img{height:280px}.menu-card{padding:20px}.menu-card p{min-height:0}.dough-circle{max-width:350px}.dough-circle .serif{font-size:38px}.pizza-cta{padding:65px 0}.cart-line{align-items:start}.qty{gap:10px}}''')
put('brasa/app.js','''const menu=[{id:'marg',name:'Margherita',price:49,group:'classicas',veg:true,tag:'A essencial',desc:'Molho de tomate, muçarela, manjericão fresco e um fio de azeite.',hue:0},{id:'pepp',name:'Pepperoni',price:59,group:'classicas',veg:false,tag:'A intensa',desc:'Muçarela, pepperoni e molho de tomate. Um clássico com personalidade.',hue:-12},{id:'brasa',name:'Brasa da casa',price:69,group:'autorais',veg:false,tag:'Receita da casa',desc:'Muçarela, linguiça artesanal, cebola roxa e toque de alecrim.',hue:12},{id:'verde',name:'Verde viva',price:55,group:'autorais',veg:true,tag:'Sem carne',desc:'Muçarela, abobrinha, tomate-cereja e folhas de manjericão.',hue:25},{id:'queijos',name:'Quatro queijos',price:62,group:'classicas',veg:true,tag:'A cremosa',desc:'Muçarela, parmesão, provolone e gorgonzola em uma combinação marcante.',hue:8},{id:'mel',name:'Queijo & mel',price:65,group:'autorais',veg:true,tag:'Encontro de sabores',desc:'Muçarela, queijo de cabra, mel e um toque de pimenta-do-reino.',hue:18}];const cart=new Map();const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);const grid=document.getElementById('menu-grid');menu.forEach(p=>{const card=document.createElement('article');card.className='menu-card';card.dataset.category=p.group;card.dataset.veg=String(p.veg);card.innerHTML=`<div class="menu-img"><img src="../assets/pizza.svg" alt="Ilustração conceitual de pizza, não representa a receita específica" loading="lazy" style="filter:hue-rotate(${p.hue}deg)"><span class="pill">${p.tag}</span></div><h3>${p.name}</h3><p>${p.desc}</p><p class="allergen">Contém trigo e leite${p.veg?' · Sem carne':''}</p><div class="menu-card-bottom"><strong>${money(p.price)}</strong><button class="add" aria-label="Adicionar ${p.name}">Adicionar +</button></div>`;card.querySelector('button').addEventListener('click',()=>{cart.set(p.id,(cart.get(p.id)||0)+1);updateCart();document.getElementById('toast').textContent=p.name+' adicionada ao pedido demonstrativo.';clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').textContent='',3000)});grid.append(card)});let toastTimer;document.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-menu]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.menu-card').forEach(x=>x.hidden=b.dataset.menu==='vegetarianas'?x.dataset.veg!=='true':b.dataset.menu!=='all'&&x.dataset.category!==b.dataset.menu)}));function updateCart(){document.getElementById('cart-count').textContent=[...cart.values()].reduce((a,b)=>a+b,0);const items=document.getElementById('cart-items');items.replaceChildren();let total=0;if(!cart.size){const p=document.createElement('p');p.textContent='Seu pedido ainda está vazio. Explore o cardápio e adicione um sabor.';items.append(p)}cart.forEach((qty,id)=>{const p=menu.find(x=>x.id===id);total+=p.price*qty;const row=document.createElement('div');row.className='cart-line';row.innerHTML=`<div><h3>${p.name}</h3><small>${money(p.price)} cada</small></div><div class="qty"><button aria-label="Remover uma ${p.name}">−</button><span>${qty}</span><button aria-label="Adicionar uma ${p.name}">+</button></div>`;row.querySelectorAll('button').forEach((b,i)=>b.addEventListener('click',()=>{const next=qty+(i?1:-1);if(next<=0)cart.delete(id);else cart.set(id,next);updateCart();const focus=document.querySelector('#cart-items button')||document.querySelector('#cart-dialog [data-close]');focus.focus()}));items.append(row)});document.getElementById('cart-total').textContent=money(total);document.getElementById('checkout').disabled=!cart.size;document.getElementById('checkout-status').textContent=''}document.getElementById('checkout').addEventListener('click',()=>{document.getElementById('checkout-status').textContent='Pedido demonstrativo conferido! Nenhum pedido foi enviado e nenhum valor será cobrado.'});updateCart();''')
